def get_lower_bound(s: str) -> int:
        s = str(s).strip()
        if 'years' in s:
            s = s.replace(' years', '')
        if s == 'None':
            return 0
        if s.endswith('+'):
            try:
                return int(s[:-1])
            except (ValueError, IndexError):
                return 0
        if '-' in s:
            try:
                return int(s.split('-')[0])
            except (ValueError, IndexError):
                return 0
